window.products.push({"id":403910,"name":"Wooden Texas Ornaments Texas 4 Pack","category":"homeandappliances","retail price":12.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/81T0u2zvkKL._AC_SL1500_.jpg","description":"These wooden Texas ornaments measure 3.5 Inches across and feature a scripty font \"Texas\" shaped cut out. Each Texas shaped ornament comes with a red ribbon, tied and ready to hang on your Christmas tree, bannister garland, door wreath, mantle or newel post. They're the perfect size at 3.5 inches and come in a convenient 4 pack. Give these as a Christmas gift or keep them for your self!","images":["https://m.media-amazon.com/images/I/81T0u2zvkKL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Texas Love","source_asin":"B09585KSTK","category_path":"Home & Kitchen"},"sku":"BM-403910","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B09585KSTK","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B09585KSTK","price_pending":true,"merchant_ready":false});
